const C=document.getElementById('game'),X=C.getContext('2d');
let W=1280,H=720,last=0,t=0,mode='menu',coop=false,shake=0,score=0,zone=0;
function resize(){W=C.width=innerWidth;H=C.height=innerHeight;X.imageSmoothingEnabled=false}addEventListener('resize',resize);resize();
const keys={},down={};addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=1;if(!down[e.key])down[e.key]=1});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=0);
const zones=[{name:'NEON DISTRICT',sky:'#071426',far:'#102d4e',ground:'#182d42',accent:'#43daf4'},{name:'CYBER FOREST',sky:'#071a1c',far:'#163c32',ground:'#1b4035',accent:'#72f09d'},{name:'THUNDER CIRCUITS',sky:'#160e38',far:'#35245e',ground:'#342761',accent:'#c36cff'}];
function rnd(a,b){return a+Math.random*(b-a)}
class Player{constructor(x,c,p=1){this.x=x;this.y=430;this.vx=0;this.vy=0;this.w=28;this.h=58;this.c=c;this.p=p;this.face=1;this.hp=100;this.core=100;this.attack=0;this.combo=0;this.rush=0;this.dodge=0;this.grab=null;this.ground=false}update(dt){let left,right,jump,atk,rush,dodge,grab;if(this.p===1){left=keys.a||keys.arrowleft;right=keys.d||keys.arrowright;jump=keys.w||keys.arrowup;atk=keys.j;rush=keys.l;dodge=keys.shift;grab=keys.i}else{left=keys['4'];right=keys['6'];jump=keys['8'];atk=keys.n;rush=keys.m;dodge=keys['0'];grab=keys['/']} 
const sp=this.rush>0?520:210;if(left){this.vx-=sp*dt*2.6;this.face=-1}if(right){this.vx+=sp*dt*2.6;this.face=1}if(!left&&!right)this.vx*=Math.pow(.03,dt);this.vx=Math.max(-sp,Math.min(sp,this.vx));
if(jump&&this.ground&&(!down._jump||this.p===2)){this.vy=-560;this.ground=false;particles(this.x,this.y+28,10,'#94efff')}down._jump=jump;
if(rush&&this.core>1){this.rush=.45;this.core-=22*dt;particles(this.x,this.vy?this.y:this.y+25,2,this.c)}else this.rush=Math.max(0,this.rush-dt);
if(dodge&&this.dodge<=0){this.dodge=.28;this.vx=this.face*540;this.core=Math.max(0,this.core-8)}this.dodge=Math.max(0,this.dodge-dt);
if(atk&&this.attack<=0){this.attack=.28;this.combo=(this.combo+1)%3;hitAttack(this,this.combo)}if(grab&&this.attack<=0){this.attack=.4;for(const e of enemies){if(Math.abs(e.x-this.x)<50&&Math.abs(e.y-this.y)<60){this.grab=e;e.grabbed=1;e.vx=this.face*240;e.vy=-220;break}}}
this.vy+=1500*dt;this.x+=this.vx*dt;this.y+=this.vy*dt;this.ground=false;
for(const p of platforms){if(this.vy>=0&&this.x>p.x&&this.x<p.x+p.w&&this.oldBottom<=p.y&&this.y+28>=p.y){this.y=p.y-28;this.vy=0;this.ground=true}}this.oldBottom=this.y+28;
if(this.y>H+100){this.hp-=20;this.x=120+(this.p-1)*50;this.y=420;this.vy=0}
this.x=Math.max(20,Math.min(worldW-20,this.x));this.attack=Math.max(0,this.attack-dt);this.core=Math.min(100,this.core+5*dt)}
 draw(){X.save();X.translate(Math.round(this.x),Math.round(this.y));X.scale(this.face,1);if(this.rush>0){for(let i=0;i<6;i++){X.fillStyle=`rgba(73,215,255,${.12-i*.015})`;X.fillRect(-35-i*12,-22+i*3,45,5)}}if(this.dodge>0){X.globalAlpha=.45}
 X.translate(0,Math.sin(t*12)*1.5);X.fillStyle='#09101e';X.fillRect(-14,-24,28,42);X.fillStyle='#d9edf0';X.fillRect(-11,-20,22,32);X.fillStyle='#111827';X.fillRect(-16,-30,32,10);X.fillStyle=this.c;X.fillRect(-18,-27,36,5);X.fillStyle='#7deaff';X.fillRect(-8,-27,16,4);X.fillStyle='#111827';X.fillRect(-12,-48,24,20);X.fillStyle='#1a2738';X.fillRect(-15,-44,30,8);X.fillStyle='#56d9ff';X.fillRect(-9,-43,18,3);X.fillStyle='#0b101a';X.fillRect(-5,-40,10,4);
 X.fillStyle='#c9dfe5';X.fillRect(-22,-16,7,28);X.fillRect(15,-16,7,28);X.fillStyle='#263d58';X.fillRect(-24,-13,10,22);X.fillRect(14,-13,10,22);
 X.fillStyle='#121725';X.fillRect(-12,15,9,16);X.fillRect(3,15,9,16);X.fillStyle='#3d8fa7';X.fillRect(-13,27,11,5);X.fillRect(2,27,11,5);
 if(this.attack>0){X.fillStyle='#89efff';X.beginPath();X.moveTo(18,-18);X.lineTo(58,-4);X.lineTo(24,10);X.fill()}X.restore()}
}
class Enemy{constructor(x,type=0){this.x=x;this.y=400;this.vx=0;this.vy=0;this.w=30;this.h=54;this.hp=3;this.type=type;this.dead=0;this.grabbed=0}update(dt){const target=players[0];let d=target.x-this.x;if(Math.abs(d)<280&&this.dead===0)this.vx+=Math.sign(d)*170*dt;this.vx*=Math.pow(.12,dt);this.vy+=1500*dt;this.x+=this.vx*dt;this.y+=this.vy*dt;for(const p of platforms){if(this.vy>=0&&this.x>p.x&&this.x<p.x+p.w&&this.y+27>=p.y&&this.y+20<=p.y){this.y=p.y-27;this.vy=0}}
 if(this.grabbed){this.x+=this.vx*dt;this.y+=this.vy*dt;this.vy+=900*dt;if(Math.abs(this.vx)>180&&this.y>300){}for(const w of walls){if(this.x>w.x&&this.x<w.x+w.w&&this.y>w.y&&this.y<w.y+w.h){this.hp-=2;this.vx=-this.vx*.35;this.vy=-180;shake=8;score+=300;w.hp--;if(w.hp<=0){w.dead=true;score+=500}}}}}
 draw(){X.save();X.translate(Math.round(this.x),Math.round(this.y));X.fillStyle=this.type?'#6f367e':'#743641';X.fillRect(-15,-24,30,46);X.fillStyle='#111827';X.fillRect(-18,-30,36,9);X.fillStyle='#ff4d88';X.fillRect(-13,-28,26,3);X.fillStyle='#d56e81';X.fillRect(-7,-44,14,16);X.fillStyle='#111827';X.fillRect(-10,-42,20,5);X.fillStyle='#ff5577';X.fillRect(-5,-40,10,3);X.fillStyle='#1c2638';X.fillRect(-12,18,8,16);X.fillRect(4,18,8,16);X.restore()}}
let players=[],enemies=[],particlesList=[],platforms=[],walls=[];
const worldW=4200;
function makeLevel(){platforms=[];walls=[];platforms.push({x:-200,y:580,w:1000,h:40},{x:900,y:510,w:500,h:35},{x:1500,y:580,w:700,h:40},{x:2300,y:470,w:600,h:35},{x:3000,y:570,w:1200,h:40},{x:1180,y:350,w:180,h:20},{x:1850,y:360,w:220,h:20},{x:2700,y:310,w:180,h:20},{x:3350,y:390,w:240,h:20});walls=[{x:760,y:430,w:55,h:80,hp:2,dead:false},{x:1420,y:500,w:55,h:80,hp:2,dead:false},{x:2180,y:390,w:55,h:80,hp:2,dead:false},{x:3230,y:490,w:55,h:80,hp:2,dead:false}]}
function particles(x,y,n,c){for(let i=0;i<n;i++)particlesList.push({x,y,vx:(Math.random-.5)*300,vy:(Math.random-.8)*240,l:Math.random*.5+.3,c})}
function hitAttack(p,k){for(const e of enemies){if(e.dead)continue;const dx=(e.x-p.x)*p.face;if(dx>10&&dx<85&&Math.abs(e.y-p.y)<65){e.hp--;e.vx=p.face*(k===2?380:220);e.vy=k===2?-230:-80;score+=100*k;shake=5;particles(e.x,e.y,10,p.c);if(e.hp<=0){e.dead=1;score+=500}}}}
function reset(){makeLevel();score=0;players=[new Player(120,'#2ed9ff',1)];if(coop)players.push(new Player(170,'#ff57c8',2));enemies=[new Enemy(650,0),new Enemy(1100,1),new Enemy(1580,0),new Enemy(2050,1),new Enemy(2700,0),new Enemy(3300,1),new Enemy(3750,0)];zone=0}
document.getElementById('single').onclick=()=>{coop=false;mode='play';document.getElementById('menu').classList.add('hidden');reset()};document.getElementById('coop').onclick=()=>{coop=true;mode='play';document.getElementById('menu').classList.add('hidden');reset()};
const pad=document.getElementById('pad');let padVec={x:0,y:0};pad.addEventListener('touchmove',e=>{const r=pad.getBoundingRect(),q=e.touches[0];padVec.x=(q.clientX-(r.left+r.width/2))/(r.width/2);padVec.y=(q.clientY-(r.top+r.height/2))/(r.height/2)});pad.addEventListener('touchend',()=>padVec={x:0,y:0});document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('touchstart',e=>{e.preventDefault();keys[b.dataset.key]=1},{passive:false}));document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('touchend',e=>{e.preventDefault();keys[b.dataset.key]=0},{passive:false}));
function update(dt){t+=dt;if(mode!=='play')return;for(const p of players)p.update(dt);for(const e of enemies){e.update(dt);if(e.dead<1&&!e.grabbed&&Math.abs(e.x-pivot(players).x)<30&&Math.abs(e.y-pivot(players).y)<55){const p=pivot(players);p.hp-=18*dt;p.dodge&&0}}
 enemies=enemies.filter(e=>e.hp>0&&e.y<H+180);particlesList.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=600*dt;p.l-=dt});particlesList=particlesList.filter(p=>p.l>0);shake*=Math.pow(.05,dt);for(const p of players){p.hp=Math.min(100,p.hp)}document.getElementById('hpbar').style.width=(players[0]?.hp||0)+'%';document.getElementById('corebar').style.width=(players[0]?.core||0)+'%';document.getElementById('score').textContent=String(score).padStart(6,'0');
 let z=Math.floor(pivot(players).x/1400);if(z!==zone&&z>=0&&z<3){zone=z;const el=document.getElementById('zone');el.textContent=zones[zone].name;el.classList.remove('show');void el.offsetWidth;el.classList.add('show')}}
function pivot(ps){return ps.reduce((a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2}),{x:ps[0]?.x||0,y:ps[0]?.y||0})}
function draw(){const z=zones[Math.max(0,Math.min(2,zone))],cam=Math.max(0,Math.min(worldW-W,pivot(players).x-W*.42));X.fillStyle=z.sky;X.fillRect(0,0,W,H);drawSky(z,cam);
 X.save();X.translate(-cam+(shake?(Math.random-.5)*shake:0),0);drawWorld(z);for(const w of walls)if(!w.dead){X.fillStyle='#e7d8aa';X.fillRect(w.x,w.y,w.w,w.h);X.fillStyle='#8aa7b0';X.fillRect(w.x+5,w.y+8,w.w-10,8)}for(const p of platforms){X.fillStyle=z.ground;X.fillRect(p.x,p.y,p.w,p.h);X.fillStyle='#9ed0d5';X.fillRect(p.x,p.y,p.w,4);X.fillStyle='#4c6471';for(let x=p.x+15;x<p.x+p.w;x+=32)X.fillRect(x,p.y+10,12,4)}for(const e of enemies)e.draw();for(const p of players)p.draw();for(const p of particlesList){X.globalAlpha=Math.min(1,p.l*2);X.fillStyle=p.c;X.fillRect(p.x,p.y,4,4)}X.globalAlpha=1;X.restore();requestAnimationFrame(loop)}
function drawSky(z,cam){let y=H*.28;X.fillStyle=z.far;for(let i=-1;i<18;i++){let x=i*180-(cam*.12%180);X.beginPath();X.moveTo(x,H*.62);X.lineTo(x+65,y+Math.sin(i)*45);X.lineTo(x+130,H*.62);X.fill()}X.fillStyle=z.accent;X.globalAlpha=.12;for(let i=0;i<20;i++){let x=(i*230-(cam*.25%230));X.fillRect(x,100+(i%4)*85,100,3)}X.globalAlpha=1}
function drawWorld(z){X.fillStyle='#020714';X.fillRect(-100,H*.82,worldW+200,H);X.fillStyle=z.accent;X.globalAlpha=.15;for(let i=0;i<worldW;i+=180){X.fillRect(i,H*.82,90,4)}X.globalAlpha=1}
function loop(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw()}reset();requestAnimationFrame(loop);
